public struct Outer: Equatable, Sendable {
    public var inner: Named
    public var pair: [Named]
    public var grid: [[Point]]
    public var tags: [Tagged]
    public var names: [Named]
    public var bigs: [Big]
    public var deep: Deep

    public init(
        inner: Named,
        pair: [Named],
        grid: [[Point]],
        tags: [Tagged],
        names: [Named],
        bigs: [Big],
        deep: Deep
    ) {
        self.inner = inner
        self.pair = pair
        self.grid = grid
        self.tags = tags
        self.names = names
        self.bigs = bigs
        self.deep = deep
    }

    public func size() -> Int {
        var size = 16
        size += inner.size()
        for item in pair {
            size += item.size()
        }
        size += 1 + tags.count * 5
        size += 1
        for item in names {
            size += item.size()
        }
        size += 1 + bigs.count * 2
        size += deep.size()
        return size
    }

    /// Writes the struct at index and returns the index just past it.
    @discardableResult
    public func toBytes(_ bytes: inout [UInt8], _ index: Int) -> Int {
        PackedWriter.write(into: &bytes, at: index) { writer in self.write(&writer) }
    }

    /// Reads the struct at index and returns it with the index just past it.
    public static func fromBytes(_ bytes: [UInt8], _ index: Int) throws -> (value: Outer, end: Int) {
        var reader = PackedReader(bytes: bytes, index: index)
        let value = try read(&reader)
        return (value, reader.index)
    }

    fileprivate func write(_ writer: inout PackedWriter) {
        writer.textUint8(inner.name)
        writer.lengthUint8(inner.points.count)
        for item in inner.points {
            writer.int16LittleEndian(item.x)
            writer.int16LittleEndian(item.y)
        }
        precondition(pair.count == 2, "pair must hold 2 items, not \(pair.count)")
        for item in pair {
            writer.textUint8(item.name)
            writer.lengthUint8(item.points.count)
            for item1 in item.points {
                writer.int16LittleEndian(item1.x)
                writer.int16LittleEndian(item1.y)
            }
        }
        precondition(grid.count == 2, "grid must hold 2 items, not \(grid.count)")
        for item in grid {
            precondition(item.count == 2, "item must hold 2 items, not \(item.count)")
            for item1 in item {
                writer.int16LittleEndian(item1.x)
                writer.int16LittleEndian(item1.y)
            }
        }
        writer.lengthUint8(tags.count)
        for item in tags {
            var itemBits0: UInt64 = 0
            itemBits0 |= UInt64(item.on ? 1 : 0)
            itemBits0 |= ((UInt64(truncatingIfNeeded: item.mode.rawValue) & 0x3) << 1)
            writer.wordLittleEndian(itemBits0, 1)
            writer.int16LittleEndian(item.at.x)
            writer.int16LittleEndian(item.at.y)
        }
        precondition(names.count <= 3, "names holds more than its maximum of 3 items")
        writer.lengthUint8(names.count)
        for item in names {
            writer.textUint8(item.name)
            writer.lengthUint8(item.points.count)
            for item1 in item.points {
                writer.int16LittleEndian(item1.x)
                writer.int16LittleEndian(item1.y)
            }
        }
        precondition(bigs.count <= 2, "bigs holds more than its maximum of 2 items")
        writer.lengthUint8(bigs.count)
        for item in bigs {
            writer.uint16BigEndian(item.value)
        }
        writer.lengthUint8(deep.level.tags.count)
        for item in deep.level.tags {
            var itemBits0: UInt64 = 0
            itemBits0 |= UInt64(item.on ? 1 : 0)
            itemBits0 |= ((UInt64(truncatingIfNeeded: item.mode.rawValue) & 0x3) << 1)
            writer.wordLittleEndian(itemBits0, 1)
            writer.int16LittleEndian(item.at.x)
            writer.int16LittleEndian(item.at.y)
        }
        writer.uint8(deep.level.mode.rawValue)
    }

    fileprivate static func read(_ reader: inout PackedReader) throws -> Outer {
        let innerName = try reader.textUint8()
        let innerPointsCount = try reader.lengthUint8()
        var innerPoints: [Point] = []
        for _ in 0..<innerPointsCount {
            let innerPointsItemX = try reader.int16LittleEndian()
            let innerPointsItemY = try reader.int16LittleEndian()
            innerPoints.append(Point(x: innerPointsItemX, y: innerPointsItemY))
        }
        let inner = Named(name: innerName, points: innerPoints)
        var pair: [Named] = []
        for _ in 0..<2 {
            let pairItemName = try reader.textUint8()
            let pairItemPointsCount = try reader.lengthUint8()
            var pairItemPoints: [Point] = []
            for _ in 0..<pairItemPointsCount {
                let pairItemPointsItemX = try reader.int16LittleEndian()
                let pairItemPointsItemY = try reader.int16LittleEndian()
                pairItemPoints.append(Point(x: pairItemPointsItemX, y: pairItemPointsItemY))
            }
            pair.append(Named(name: pairItemName, points: pairItemPoints))
        }
        var grid: [[Point]] = []
        for _ in 0..<2 {
            var gridItem: [Point] = []
            for _ in 0..<2 {
                let gridItemItemX = try reader.int16LittleEndian()
                let gridItemItemY = try reader.int16LittleEndian()
                gridItem.append(Point(x: gridItemItemX, y: gridItemItemY))
            }
            grid.append(gridItem)
        }
        let tagsCount = try reader.lengthUint8()
        var tags: [Tagged] = []
        for _ in 0..<tagsCount {
            let tagsItemBits0 = try reader.wordLittleEndian(1)
            let tagsItemOn = (tagsItemBits0 & 0x1) != 0
            let tagsItemMode = try Mode(validating: UInt8(truncatingIfNeeded: ((tagsItemBits0 >> 1) & 0x3)))
            let tagsItemAtX = try reader.int16LittleEndian()
            let tagsItemAtY = try reader.int16LittleEndian()
            let tagsItemAt = Point(x: tagsItemAtX, y: tagsItemAtY)
            tags.append(Tagged(on: tagsItemOn, mode: tagsItemMode, at: tagsItemAt))
        }
        let namesCount = try reader.lengthUint8()
        guard namesCount <= 3 else {
            throw PackedError.overMaximum(field: "names", count: namesCount)
        }
        var names: [Named] = []
        for _ in 0..<namesCount {
            let namesItemName = try reader.textUint8()
            let namesItemPointsCount = try reader.lengthUint8()
            var namesItemPoints: [Point] = []
            for _ in 0..<namesItemPointsCount {
                let namesItemPointsItemX = try reader.int16LittleEndian()
                let namesItemPointsItemY = try reader.int16LittleEndian()
                namesItemPoints.append(Point(x: namesItemPointsItemX, y: namesItemPointsItemY))
            }
            names.append(Named(name: namesItemName, points: namesItemPoints))
        }
        let bigsCount = try reader.lengthUint8()
        guard bigsCount <= 2 else {
            throw PackedError.overMaximum(field: "bigs", count: bigsCount)
        }
        var bigs: [Big] = []
        for _ in 0..<bigsCount {
            let bigsItemValue = try reader.uint16BigEndian()
            bigs.append(Big(value: bigsItemValue))
        }
        let deepLevelTagsCount = try reader.lengthUint8()
        var deepLevelTags: [Tagged] = []
        for _ in 0..<deepLevelTagsCount {
            let deepLevelTagsItemBits0 = try reader.wordLittleEndian(1)
            let deepLevelTagsItemOn = (deepLevelTagsItemBits0 & 0x1) != 0
            let deepLevelTagsItemMode = try Mode(validating: UInt8(truncatingIfNeeded: ((deepLevelTagsItemBits0 >> 1) & 0x3)))
            let deepLevelTagsItemAtX = try reader.int16LittleEndian()
            let deepLevelTagsItemAtY = try reader.int16LittleEndian()
            let deepLevelTagsItemAt = Point(x: deepLevelTagsItemAtX, y: deepLevelTagsItemAtY)
            deepLevelTags.append(Tagged(on: deepLevelTagsItemOn, mode: deepLevelTagsItemMode, at: deepLevelTagsItemAt))
        }
        let deepLevelMode = try Mode(validating: reader.uint8())
        let deepLevel = Deeper(tags: deepLevelTags, mode: deepLevelMode)
        let deep = Deep(level: deepLevel)
        return Outer(
            inner: inner,
            pair: pair,
            grid: grid,
            tags: tags,
            names: names,
            bigs: bigs,
            deep: deep
        )
    }
}

