public struct Record: Equatable, Sendable {
    public var id: UInt32
    public var name: String
    public var severity: Severity
    public var signed: Signed
    public var flags: RecordFlags
    public var labels: [Label]
    public var values: [Int16]
    public var trailer: UInt16
    public var pair: [String]
    public var nested: [[UInt8]]
    public var severities: [Severity]
    public var matrix: [[Int16]]

    public init(
        id: UInt32,
        name: String,
        severity: Severity,
        signed: Signed,
        flags: RecordFlags,
        labels: [Label],
        values: [Int16],
        trailer: UInt16,
        pair: [String],
        nested: [[UInt8]],
        severities: [Severity],
        matrix: [[Int16]]
    ) {
        self.id = id
        self.name = name
        self.severity = severity
        self.signed = signed
        self.flags = flags
        self.labels = labels
        self.values = values
        self.trailer = trailer
        self.pair = pair
        self.nested = nested
        self.severities = severities
        self.matrix = matrix
    }

    public func size() -> Int {
        var size = 18
        size += 2 + name.utf8.count
        size += 1
        for item in labels {
            size += item.size()
        }
        size += 2 + values.count * 2
        for item in pair {
            size += 1 + item.utf8.count
        }
        size += 1
        for item in nested {
            size += 4 + item.count * 1
        }
        size += 1 + severities.count * 1
        return size
    }

    /// Writes the struct at index and returns the index just past it.
    @discardableResult
    public func toBytes(_ bytes: inout [UInt8], _ index: Int) -> Int {
        PackedWriter.write(into: &bytes, at: index) { writer in self.write(&writer) }
    }

    /// Reads the struct at index and returns it with the index just past it.
    public static func fromBytes(_ bytes: [UInt8], _ index: Int) throws -> (value: Record, end: Int) {
        var reader = PackedReader(bytes: bytes, index: index)
        let value = try read(&reader)
        return (value, reader.index)
    }

    /// The type byte followed by the struct after prefix, as the message set sends it.
    public func encode(prefix: [UInt8] = []) -> [UInt8] {
        var bytes = prefix
        bytes.append(contentsOf: repeatElement(0, count: 1 + size()))
        bytes[prefix.count] = 7
        toBytes(&bytes, prefix.count + 1)
        return bytes
    }

    fileprivate func write(_ writer: inout PackedWriter) {
        writer.uint32LittleEndian(id)
        writer.textUint16LittleEndian(name)
        writer.uint8(severity.rawValue)
        writer.int16LittleEndian(signed.rawValue)
        var flagsBits0: UInt64 = 0
        flagsBits0 |= UInt64(flags.active ? 1 : 0)
        flagsBits0 |= ((UInt64(truncatingIfNeeded: flags.level) & 0x7) << 1)
        writer.wordLittleEndian(flagsBits0, 1)
        precondition(labels.count <= 4, "labels holds more than its maximum of 4 items")
        writer.lengthUint8(labels.count)
        for item in labels {
            writer.textUint8(item.name)
            writer.float32LittleEndian(item.weight)
        }
        precondition(values.count <= 4, "values holds more than its maximum of 4 items")
        writer.lengthUint16LittleEndian(values.count)
        for item in values {
            writer.int16LittleEndian(item)
        }
        writer.uint16BigEndian(trailer)
        precondition(pair.count == 2, "pair must hold 2 items, not \(pair.count)")
        for item in pair {
            writer.textUint8(item)
        }
        precondition(nested.count <= 4, "nested holds more than its maximum of 4 items")
        writer.lengthUint8(nested.count)
        for item in nested {
            writer.lengthUint32LittleEndian(item.count)
            for item1 in item {
                writer.uint8(item1)
            }
        }
        precondition(severities.count <= 4, "severities holds more than its maximum of 4 items")
        writer.lengthUint8(severities.count)
        for item in severities {
            writer.uint8(item.rawValue)
        }
        precondition(matrix.count == 2, "matrix must hold 2 items, not \(matrix.count)")
        for item in matrix {
            precondition(item.count == 2, "item must hold 2 items, not \(item.count)")
            for item1 in item {
                writer.int16LittleEndian(item1)
            }
        }
    }

    fileprivate static func read(_ reader: inout PackedReader) throws -> Record {
        let id = try reader.uint32LittleEndian()
        let name = try reader.textUint16LittleEndian()
        let severity = try Severity(validating: reader.uint8())
        let signed = try Signed(validating: reader.int16LittleEndian())
        let flagsBits0 = try reader.wordLittleEndian(1)
        let flagsActive = (flagsBits0 & 0x1) != 0
        let flagsLevel = UInt8(truncatingIfNeeded: ((flagsBits0 >> 1) & 0x7))
        let flags = RecordFlags(active: flagsActive, level: flagsLevel)
        let labelsCount = try reader.lengthUint8()
        guard labelsCount <= 4 else {
            throw PackedError.overMaximum(field: "labels", count: labelsCount)
        }
        var labels: [Label] = []
        for _ in 0..<labelsCount {
            let labelsItemName = try reader.textUint8()
            let labelsItemWeight = try reader.float32LittleEndian()
            labels.append(Label(name: labelsItemName, weight: labelsItemWeight))
        }
        let valuesCount = try reader.lengthUint16LittleEndian()
        guard valuesCount <= 4 else {
            throw PackedError.overMaximum(field: "values", count: valuesCount)
        }
        var values: [Int16] = []
        for _ in 0..<valuesCount {
            values.append(try reader.int16LittleEndian())
        }
        let trailer = try reader.uint16BigEndian()
        var pair: [String] = []
        for _ in 0..<2 {
            pair.append(try reader.textUint8())
        }
        let nestedCount = try reader.lengthUint8()
        guard nestedCount <= 4 else {
            throw PackedError.overMaximum(field: "nested", count: nestedCount)
        }
        var nested: [[UInt8]] = []
        for _ in 0..<nestedCount {
            let nestedItemCount = try reader.lengthUint32LittleEndian()
            var nestedItem: [UInt8] = []
            for _ in 0..<nestedItemCount {
                nestedItem.append(try reader.uint8())
            }
            nested.append(nestedItem)
        }
        let severitiesCount = try reader.lengthUint8()
        guard severitiesCount <= 4 else {
            throw PackedError.overMaximum(field: "severities", count: severitiesCount)
        }
        var severities: [Severity] = []
        for _ in 0..<severitiesCount {
            severities.append(try Severity(validating: reader.uint8()))
        }
        var matrix: [[Int16]] = []
        for _ in 0..<2 {
            var matrixItem: [Int16] = []
            for _ in 0..<2 {
                matrixItem.append(try reader.int16LittleEndian())
            }
            matrix.append(matrixItem)
        }
        return Record(
            id: id,
            name: name,
            severity: severity,
            signed: signed,
            flags: flags,
            labels: labels,
            values: values,
            trailer: trailer,
            pair: pair,
            nested: nested,
            severities: severities,
            matrix: matrix
        )
    }
}

