fileprivate struct PackedWriter {
    var bytes: [UInt8] = []
    var index: Int

    /// Runs body on a writer that owns bytes for the duration, so writes
    /// do not copy the array.
    static func write(into bytes: inout [UInt8], at index: Int, _ body: (inout PackedWriter) -> Void) -> Int {
        var writer = PackedWriter(index: index)
        swap(&bytes, &writer.bytes)
        body(&writer)
        swap(&bytes, &writer.bytes)
        return writer.index
    }

    mutating func boolean(_ value: Bool) {
        bytes[index] = value ? 1 : 0
        index += 1
    }

    mutating func bytesUint16LittleEndian(_ value: [UInt8]) {
        let length = value.count
        precondition(length <= 65535, "\(length) bytes do not fit a UInt16 length prefix")
        wordLittleEndian(UInt64(length), 2)
        bytes.replaceSubrange(index..<index + length, with: value)
        index += length
    }

    mutating func bytesUint32LittleEndian(_ value: [UInt8]) {
        let length = value.count
        precondition(UInt64(length) <= 4294967295, "\(length) bytes do not fit a UInt32 length prefix")
        wordLittleEndian(UInt64(length), 4)
        bytes.replaceSubrange(index..<index + length, with: value)
        index += length
    }

    mutating func bytesUint8(_ value: [UInt8]) {
        let length = value.count
        precondition(length <= 255, "\(length) bytes do not fit a UInt8 length prefix")
        bytes[index] = UInt8(length)
        index += 1
        bytes.replaceSubrange(index..<index + length, with: value)
        index += length
    }

    mutating func fixedText(_ value: String, _ length: Int) {
        var count = 0
        for byte in value.utf8.prefix(length) {
            bytes[index + count] = byte
            count += 1
        }
        for offset in count..<length {
            bytes[index + offset] = 0
        }
        index += length
    }

    mutating func float32BigEndian(_ value: Float) {
        wordBigEndian(UInt64(value.bitPattern), 4)
    }

    mutating func float32LittleEndian(_ value: Float) {
        wordLittleEndian(UInt64(value.bitPattern), 4)
    }

    mutating func float64BigEndian(_ value: Double) {
        wordBigEndian(UInt64(value.bitPattern), 8)
    }

    mutating func int16BigEndian(_ value: Int16) {
        wordBigEndian(UInt64(truncatingIfNeeded: value), 2)
    }

    mutating func int16LittleEndian(_ value: Int16) {
        wordLittleEndian(UInt64(truncatingIfNeeded: value), 2)
    }

    mutating func int32BigEndian(_ value: Int32) {
        wordBigEndian(UInt64(truncatingIfNeeded: value), 4)
    }

    mutating func int32LittleEndian(_ value: Int32) {
        wordLittleEndian(UInt64(truncatingIfNeeded: value), 4)
    }

    mutating func int64BigEndian(_ value: Int64) {
        wordBigEndian(UInt64(truncatingIfNeeded: value), 8)
    }

    mutating func int8(_ value: Int8) {
        bytes[index] = UInt8(bitPattern: value)
        index += 1
    }

    mutating func lengthUint16LittleEndian(_ length: Int) {
        precondition(length <= 65535, "\(length) items do not fit a UInt16 length prefix")
        wordLittleEndian(UInt64(length), 2)
    }

    mutating func lengthUint32LittleEndian(_ length: Int) {
        precondition(UInt64(length) <= 4294967295, "\(length) items do not fit a UInt32 length prefix")
        wordLittleEndian(UInt64(length), 4)
    }

    mutating func lengthUint8(_ length: Int) {
        precondition(length <= 255, "\(length) items do not fit a UInt8 length prefix")
        bytes[index] = UInt8(length)
        index += 1
    }

    mutating func textUint16LittleEndian(_ value: String) {
        let length = value.utf8.count
        precondition(length <= 65535, "\(length) bytes do not fit a UInt16 length prefix")
        wordLittleEndian(UInt64(length), 2)
        for byte in value.utf8 {
            bytes[index] = byte
            index += 1
        }
    }

    mutating func textUint8(_ value: String) {
        let length = value.utf8.count
        precondition(length <= 255, "\(length) bytes do not fit a UInt8 length prefix")
        bytes[index] = UInt8(length)
        index += 1
        for byte in value.utf8 {
            bytes[index] = byte
            index += 1
        }
    }

    mutating func uint16BigEndian(_ value: UInt16) {
        wordBigEndian(UInt64(truncatingIfNeeded: value), 2)
    }

    mutating func uint16LittleEndian(_ value: UInt16) {
        wordLittleEndian(UInt64(truncatingIfNeeded: value), 2)
    }

    mutating func uint32BigEndian(_ value: UInt32) {
        wordBigEndian(UInt64(truncatingIfNeeded: value), 4)
    }

    mutating func uint32LittleEndian(_ value: UInt32) {
        wordLittleEndian(UInt64(truncatingIfNeeded: value), 4)
    }

    mutating func uint64BigEndian(_ value: UInt64) {
        wordBigEndian(UInt64(truncatingIfNeeded: value), 8)
    }

    mutating func uint8(_ value: UInt8) {
        bytes[index] = value
        index += 1
    }

    mutating func wordBigEndian(_ value: UInt64, _ size: Int) {
        for byte in 0..<size {
            bytes[index + size - 1 - byte] = UInt8(truncatingIfNeeded: value >> (8 * byte))
        }
        index += size
    }

    mutating func wordLittleEndian(_ value: UInt64, _ size: Int) {
        for byte in 0..<size {
            bytes[index + byte] = UInt8(truncatingIfNeeded: value >> (8 * byte))
        }
        index += size
    }
}

fileprivate struct PackedReader {
    let bytes: [UInt8]
    var index: Int

    mutating func advance(_ size: Int) throws -> Int {
        guard index >= 0, size <= bytes.count - index else {
            throw PackedError.truncated
        }
        let start = index
        index += size
        return start
    }

    mutating func boolean() throws -> Bool {
        return try bytes[advance(1)] != 0
    }

    mutating func bytesUint16LittleEndian() throws -> [UInt8] {
        let length = try lengthUint16LittleEndian()
        let start = try advance(length)
        return Array(bytes[start..<start + length])
    }

    mutating func bytesUint32LittleEndian() throws -> [UInt8] {
        let length = try lengthUint32LittleEndian()
        let start = try advance(length)
        return Array(bytes[start..<start + length])
    }

    mutating func bytesUint8() throws -> [UInt8] {
        let length = try lengthUint8()
        let start = try advance(length)
        return Array(bytes[start..<start + length])
    }

    mutating func fixedText(_ length: Int) throws -> String {
        let start = try advance(length)
        var end = start + length
        while end > start && bytes[end - 1] == 0 {
            end -= 1
        }
        return String(decoding: bytes[start..<end], as: UTF8.self)
    }

    mutating func float32BigEndian() throws -> Float {
        return try Float(bitPattern: UInt32(truncatingIfNeeded: wordBigEndian(4)))
    }

    mutating func float32LittleEndian() throws -> Float {
        return try Float(bitPattern: UInt32(truncatingIfNeeded: wordLittleEndian(4)))
    }

    mutating func float64BigEndian() throws -> Double {
        return try Double(bitPattern: wordBigEndian(8))
    }

    mutating func int16BigEndian() throws -> Int16 {
        return try Int16(truncatingIfNeeded: wordBigEndian(2))
    }

    mutating func int16LittleEndian() throws -> Int16 {
        return try Int16(truncatingIfNeeded: wordLittleEndian(2))
    }

    mutating func int32BigEndian() throws -> Int32 {
        return try Int32(truncatingIfNeeded: wordBigEndian(4))
    }

    mutating func int32LittleEndian() throws -> Int32 {
        return try Int32(truncatingIfNeeded: wordLittleEndian(4))
    }

    mutating func int64BigEndian() throws -> Int64 {
        return try Int64(truncatingIfNeeded: wordBigEndian(8))
    }

    mutating func int8() throws -> Int8 {
        return try Int8(bitPattern: bytes[advance(1)])
    }

    mutating func lengthUint16LittleEndian() throws -> Int {
        return try Int(wordLittleEndian(2))
    }

    mutating func lengthUint32LittleEndian() throws -> Int {
        guard let length = Int(exactly: try wordLittleEndian(4)) else {
            throw PackedError.truncated
        }
        return length
    }

    mutating func lengthUint8() throws -> Int {
        return try Int(bytes[advance(1)])
    }

    mutating func textUint16LittleEndian() throws -> String {
        let length = try lengthUint16LittleEndian()
        let start = try advance(length)
        return String(decoding: bytes[start..<start + length], as: UTF8.self)
    }

    mutating func textUint8() throws -> String {
        let length = try lengthUint8()
        let start = try advance(length)
        return String(decoding: bytes[start..<start + length], as: UTF8.self)
    }

    mutating func uint16BigEndian() throws -> UInt16 {
        return try UInt16(truncatingIfNeeded: wordBigEndian(2))
    }

    mutating func uint16LittleEndian() throws -> UInt16 {
        return try UInt16(truncatingIfNeeded: wordLittleEndian(2))
    }

    mutating func uint32BigEndian() throws -> UInt32 {
        return try UInt32(truncatingIfNeeded: wordBigEndian(4))
    }

    mutating func uint32LittleEndian() throws -> UInt32 {
        return try UInt32(truncatingIfNeeded: wordLittleEndian(4))
    }

    mutating func uint64BigEndian() throws -> UInt64 {
        return try UInt64(truncatingIfNeeded: wordBigEndian(8))
    }

    mutating func uint8() throws -> UInt8 {
        return try bytes[advance(1)]
    }

    mutating func wordBigEndian(_ size: Int) throws -> UInt64 {
        let start = try advance(size)
        var value: UInt64 = 0
        for byte in 0..<size {
            value |= UInt64(bytes[start + size - 1 - byte]) << (8 * byte)
        }
        return value
    }

    mutating func wordLittleEndian(_ size: Int) throws -> UInt64 {
        let start = try advance(size)
        var value: UInt64 = 0
        for byte in 0..<size {
            value |= UInt64(bytes[start + byte]) << (8 * byte)
        }
        return value
    }
}
